# Select candidate based on D4 orbit; validate all demo pairs against same transform.
def transform(grid):
 n=len(grid); out=[row[:] for row in grid]
 for i in range(n):
  for j in range(n):
   if grid[i][j]==2:
    orbit=d4maps(i,j,n)
    candidates=[grid[a][b] for a,b in orbit if grid[a][b]!=2]
    if not candidates: raise ValueError(f'No symmetry source at {(i,j)}')
    if len(set(candidates))!=1: raise ValueError(f'Conflicting symmetry sources at {(i,j)}: {candidates}')
    out[i][j]=candidates[0]
 return out
